python3 -c $'import sys,math,json\nN=int(sys.argv[1])if len(sys.argv)>1 else 100000;lam=float(sys.argv[2])if len(sys.argv)>2 else .01;eps=1e-12\ndef D(n):\n b=[]\n while n>1:\n  n,r=divmod(n,257)\n  if not r:raise ValueError\n  b[:0]=[r-1]\n return bytes(b)\ndef G(b):\n n=1\n for v in b:n=n*257+v+1\n return n\ndef H(b):\n return-sum((b.count(v)/len(b))*math.log2(b.count(v)/len(b))for v in set(b))\nC=[]\nfor e in range(1,N+1):\n try:b=D(e)\n except ValueError:continue\n if b and b"S"in b and G(b)==e:C.append((e,b,H(b)+lam*len(b)))\nassert C,"increase N to at least 341"\nm=min(x[2]for x in C);W=[x for x in C if abs(x[2]-m)<=eps];beta=1.\nfor k in range(64):\n w=[math.exp(-beta*(x[2]-m))for x in C];z=sum(w);p=[v/z for v in w];h=-sum(q*math.log2(q)for q in p if q)\n if h<=eps:break\n beta*=2\ne,b,j=min(W,key=lambda x:(len(x[1]),x[0]));unique=len(W)==1;r={"model":"Quantum Ultimate Schumann Machine","encoding":"base257 byte+1; |e>","quantum_state":"rho=sum p(e)|e><e|","pure_state":"psi=sum sqrt(p(e))|e>","N":N,"lambda":lam,"candidates":len(C),"beta":beta,"von_neumann_bits":h,"limit_entropy_bits":0 if unique else math.log2(len(W)),"unique":unique,"prototype":{"code":e,"program_hex":b.hex(),"SELF":e},"fixed_point_encoding":e==G(b),"scope":"classical simulation of quantum encoding; no quantum speedup or halting oracle"}\nprint(json.dumps(r,separators=(",",":")))' "$@"
